//! Putting a node's WireGuard configuration in place, and keeping it current.
//!
//! The configuration itself is generated by `hlb-mesh`; this module only decides the
//! steps that apply it on the machine, as [`crate::provision::Step`]s, so they print
//! before they run like everything else the bootstrap does.
//!
//! ## 🔴 An interface already up is synchronised, never restarted
//!
//! Every node's configuration changes whenever a node joins: each lists every peer. On
//! a node already in the cluster, restarting `wg-quick` drops the tunnel that carries
//! Swarm's own traffic — the node leaves the Raft quorum for a moment, and a manager
//! doing so while another is down stops the cluster scheduling anything. `wg syncconf`
//! applies the new peers to the live interface without touching the existing ones.

use crate::provision::{Action, Init, Phase, Step};

/// Which WireGuard tunnel the steps are for: the mesh, or the link to a site.
///
/// 🔴 Each has unit files of its own. With the mesh's names fixed, the site's link would
/// have rewritten Docker's `hlb-mesh.conf` drop-in to wait for `hlb-site` instead of
/// `hlb0`: Docker starting before the mesh after the next reboot, and the node out of
/// the Swarm, with nothing to say why.
#[derive(Debug, Clone, Copy)]
pub struct Tunnel<'a> {
    /// How the preview names it: "the mesh".
    pub label: &'a str,
    /// The name its OpenRC service and its Docker drop-in carry.
    pub unit: &'a str,
    pub interface: &'a str,
    pub config_path: &'a str,
    pub firewall_path: &'a str,
}

/// The steps that bring a tunnel up, or bring it up to date.
///
/// `Err` on an init system the steps cannot drive: the configuration is then for a
/// person to put in place, and they are told where.
pub fn steps(
    init: Init,
    tunnel: &Tunnel<'_>,
    config: &str,
    firewall: &str,
) -> Result<Vec<Step>, String> {
    let Tunnel {
        label,
        unit,
        interface,
        config_path,
        firewall_path,
    } = *tunnel;
    let install = |what: &str, path: &str, content: &str, mode| Step {
        phase: Phase::Configuration,
        what: what.to_string(),
        action: Action::Install {
            path: path.to_string(),
            content: content.to_string(),
            mode,
        },
    };
    let run = |what: &str, argv: Vec<String>| Step {
        phase: Phase::Services,
        what: what.to_string(),
        action: Action::Run(argv),
    };
    let sh = |script: String| vec!["sh".to_string(), "-c".to_string(), script];

    let mut out = vec![
        install(
            &format!("{label}'s firewall rules"),
            firewall_path,
            firewall,
            0o600,
        ),
        // 0600: it carries the node's private key.
        install(
            &format!("{label}'s configuration"),
            config_path,
            config,
            0o600,
        ),
    ];
    // Synchronised in place when the interface is up, started otherwise: the same on
    // both inits, only the starting differs.
    let bring_up = |start: &str| {
        sh(format!(
            "set -e; if ip link show {interface} >/dev/null 2>&1; then \
               umask 077; wg-quick strip {config_path} > /run/{interface}.sync; \
               wg syncconf {interface} /run/{interface}.sync; rm -f /run/{interface}.sync; \
               nft -f {firewall_path}; \
             else {start}; fi"
        ))
    };

    if init == Init::OpenRc {
        // Alpine has no `wg-quick@` unit: a service of our own, ordered before Docker
        // for the same reason as the systemd drop-in below.
        out.push(install(
            &format!("{label}'s service, started before Docker"),
            &format!("/etc/init.d/{unit}"),
            &format!(
                "#!/sbin/openrc-run\n\
                 # Written by Homelabus: Swarm may listen on its address.\n\
                 description=\"Homelabus WireGuard, {label} ({interface})\"\n\
                 depend() {{\n\
                 \tneed net\n\
                 \tbefore docker\n\
                 }}\n\
                 start() {{\n\
                 \tebegin \"Bringing up {interface}\"\n\
                 \twg-quick up {config_path}\n\
                 \teend $?\n\
                 }}\n\
                 stop() {{\n\
                 \tebegin \"Bringing down {interface}\"\n\
                 \twg-quick down {config_path}\n\
                 \teend $?\n\
                 }}\n"
            ),
            0o755,
        ));
        out.push(run(
            &format!("start {label} at every boot"),
            vec![
                "rc-update".into(),
                "add".into(),
                unit.into(),
                "default".into(),
            ],
        ));
        out.push(run(
            &format!("bring {label} up, or synchronise it in place"),
            bring_up(&format!("rc-service {unit} start")),
        ));
        return Ok(out);
    }

    out.extend([
        // Docker started before the tunnel cannot bind Swarm to an address that does
        // not exist yet, and the node comes back from a reboot out of the cluster.
        install(
            &format!("start Docker after {label}"),
            &format!("/etc/systemd/system/docker.service.d/{unit}.conf"),
            &format!(
                "# Written by Homelabus: Swarm may listen on its address.\n\
                 [Unit]\n\
                 After=wg-quick@{interface}.service\n\
                 Wants=wg-quick@{interface}.service\n"
            ),
            0o644,
        ),
        run(
            "reload systemd's units",
            vec!["systemctl".into(), "daemon-reload".into()],
        ),
        run(
            &format!("start {label} at every boot"),
            vec![
                "systemctl".into(),
                "enable".into(),
                format!("wg-quick@{interface}"),
            ],
        ),
        run(
            &format!("bring {label} up, or synchronise it in place"),
            bring_up(&format!("systemctl start wg-quick@{interface}")),
        ),
    ]);
    Ok(out)
}

/// The command that proves the tunnel carries traffic to `peer`: three pings, two
/// seconds each. A handshake alone is not enough — it succeeds with the wrong
/// `AllowedIPs`, and the traffic then goes nowhere.
pub fn reachability_check(peer_ip: &str) -> Vec<String> {
    vec![
        "ping".into(),
        "-c".into(),
        "3".into(),
        "-W".into(),
        "2".into(),
        peer_ip.into(),
    ]
}

#[cfg(test)]
mod tests {
    use super::*;

    const MESH: Tunnel<'static> = Tunnel {
        label: "the mesh",
        unit: "hlb-mesh",
        interface: "hlb0",
        config_path: "/etc/wireguard/hlb0.conf",
        firewall_path: "/etc/wireguard/hlb0.nft",
    };

    const SITE: Tunnel<'static> = Tunnel {
        label: "the site link",
        unit: "hlb-site",
        interface: "hlb-site",
        config_path: "/etc/wireguard/hlb-site.conf",
        firewall_path: "/etc/wireguard/hlb-site.nft",
    };

    fn the_steps() -> Vec<Step> {
        steps(
            Init::Systemd,
            &MESH,
            "[Interface]\nPrivateKey = secret\n",
            "table inet hlb_swarm\n",
        )
        .expect("systemd")
    }

    fn paths(s: &[Step]) -> Vec<String> {
        s.iter()
            .filter_map(|s| match &s.action {
                Action::Install { path, .. } => Some(path.clone()),
                Action::Run(_) => None,
            })
            .collect()
    }

    #[test]
    fn two_tunnels_never_write_each_others_files() {
        // 🔴 The site's link rewriting the mesh's Docker drop-in would leave Docker
        // starting before the mesh at the next boot, and the node out of the Swarm.
        for init in [Init::Systemd, Init::OpenRc] {
            let mesh = paths(&steps(init, &MESH, "", "").expect("mesh"));
            let site = paths(&steps(init, &SITE, "", "").expect("site"));
            for p in &site {
                assert!(!mesh.contains(p), "{init:?}: both tunnels write {p}");
            }
        }
    }

    #[test]
    fn the_private_key_is_written_readable_by_root_only() {
        let s = the_steps();
        let conf = s
            .iter()
            .find_map(|s| match &s.action {
                Action::Install { path, mode, .. } if path.ends_with("hlb0.conf") => Some(*mode),
                _ => None,
            })
            .expect("the configuration");
        assert_eq!(conf, 0o600);
    }

    #[test]
    fn a_live_interface_is_synchronised_never_restarted() {
        let s = the_steps();
        let up = s
            .iter()
            .find_map(|s| match &s.action {
                Action::Run(a) if a.join(" ").contains("syncconf") => Some(a.join(" ")),
                _ => None,
            })
            .expect("the bring-up");
        assert!(up.contains("wg syncconf hlb0"));
        assert!(!up.contains("restart"));
    }

    #[test]
    fn docker_waits_for_the_mesh_at_boot() {
        let s = the_steps();
        assert!(s.iter().any(|s| matches!(&s.action,
            Action::Install { path, content, .. }
                if path.contains("docker.service.d") && content.contains("After=wg-quick@hlb0.service"))));
    }

    #[test]
    fn the_firewall_is_in_place_before_the_interface_loads_it() {
        let s = the_steps();
        let fw = s
            .iter()
            .position(
                |s| matches!(&s.action, Action::Install { path, .. } if path.ends_with(".nft")),
            )
            .expect("firewall");
        let up = s
            .iter()
            .position(|s| matches!(&s.action, Action::Run(a) if a.join(" ").contains("wg-quick")))
            .expect("bring-up");
        assert!(fw < up);
    }

    #[test]
    fn openrc_gets_a_service_of_its_own_ordered_before_docker() {
        let s = steps(
            Init::OpenRc,
            &MESH,
            "[Interface]\n",
            "table inet hlb_swarm\n",
        )
        .expect("openrc");
        let script = s
            .iter()
            .find_map(|s| match &s.action {
                Action::Install { path, content, .. } if path == "/etc/init.d/hlb-mesh" => {
                    Some(content.clone())
                }
                _ => None,
            })
            .expect("an init script");
        assert!(script.starts_with("#!/sbin/openrc-run"));
        assert!(script.contains("before docker"));
        assert!(!s
            .iter()
            .any(|s| matches!(&s.action, Action::Run(a) if a.join(" ").contains("systemctl"))));
    }
}
